using System;
using System.IO;
using System.Linq;
using Planetbase;
using PlanetbaseCommunityExpansion;
using UnityEngine;
using Object=UnityEngine.Object;
internal static class Studio
{
 static string output;static int index,frame;static float at;static Action done;static Camera camera;static RenderTexture texture;static GameObject stage,model,floor;
 static readonly string[] Ids=Catalog.All.Keys.Select(id=>Catalog.All[id].Group=="equipo"||Catalog.All[id].Group=="recurso"?id:"ModuleType"+id).Concat(new[]{"FreightHauler","RescueRover","ExpeditionRover","PatrolCar","Discovery0","Discovery1","Discovery2","TradeShuttle"}).ToArray();
 internal static void Begin(string folder,Action finish){output=Path.Combine(folder,"modelos");Directory.CreateDirectory(output);done=finish;stage=new GameObject("Community QA studio");stage.transform.position=new Vector3(0,200,0);var cam=new GameObject("Community studio camera");camera=cam.AddComponent<Camera>();camera.enabled=false;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.105f,.14f,.17f);camera.orthographic=true;camera.cullingMask=1<<29;camera.nearClipPlane=.05f;camera.farClipPlane=120;camera.renderingPath=RenderingPath.DeferredShading;texture=new RenderTexture(1100,850,24);texture.Create();camera.targetTexture=texture;camera.aspect=1100f/850;floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.SetParent(stage.transform,false);floor.layer=29;floor.GetComponent<Collider>().enabled=false;floor.GetComponent<Renderer>().sharedMaterial=new Material(Shader.Find("Standard")){color=new Color(.13f,.17f,.2f)};Pose();}
 static void Pose(){if(model!=null){model.SetActive(false);Object.Destroy(model);}string id=Ids[index];if(id.StartsWith("ModuleType")){var type=TypeList<ModuleType,ModuleTypeList>.find(id);model=type.createModel(type.getMinSize());}else if(Catalog.IsEquipment(id))model=TypeList<ComponentType,ComponentTypeList>.find(id).createModel();else if(Catalog.All.TryGetValue(id,out var entry)&&entry.Group=="recurso")model=TypeList<ResourceType,ResourceTypeList>.find(id).createModel();else if(id.StartsWith("Discovery")){model=new GameObject(id);SiteScene.BuildSite(model.transform,int.Parse(id.Substring(9)));}else if(id=="PatrolCar")model=CommunityModels.Vehicle(stage.transform,id);else if(id=="TradeShuttle")model=(GameObject)HarmonyLib.AccessTools.Method(typeof(CommunityModels),"Ship").Invoke(null,new object[]{stage.transform});else model=TypeList<Specialization,SpecializationList>.find(id).createModelExterior(new ObjectList<Material>());model.transform.SetParent(stage.transform,false);model.transform.localPosition=Vector3.zero;model.transform.localRotation=Quaternion.identity;model.disablePhysics();foreach(var t in model.GetComponentsInChildren<Transform>(true))t.gameObject.layer=29;frame=Time.frameCount+4;at=Time.realtimeSinceStartup+.25f;}
 internal static void Update(){if(Time.frameCount<frame||Time.realtimeSinceStartup<at)return;var renderers=model.GetComponentsInChildren<Renderer>(false).Where(r=>r.enabled&&!r.forceRenderingOff).ToArray();if(renderers.Length==0)throw new Exception("No studio geometry: "+Ids[index]);var b=renderers[0].bounds;foreach(var r in renderers)b.Encapsulate(r.bounds);b.Encapsulate(new Vector3(b.center.x,stage.transform.position.y,b.center.z));float diameter=Mathf.Max(b.size.x,b.size.z);floor.transform.position=new Vector3(b.center.x,stage.transform.position.y-.07f,b.center.z);floor.transform.localScale=new Vector3(diameter*1.2f,.08f,diameter*1.2f);var q=Quaternion.LookRotation(new Vector3(-1,-.72f,-1));camera.transform.rotation=q;camera.transform.position=b.center-q*Vector3.forward*30;float h=0,w=0;for(int x=-1;x<=1;x+=2)for(int y=-1;y<=1;y+=2)for(int z=-1;z<=1;z+=2){var p=camera.transform.InverseTransformPoint(b.center+Vector3.Scale(b.extents,new Vector3(x,y,z)));h=Mathf.Max(h,Mathf.Abs(p.y));w=Mathf.Max(w,Mathf.Abs(p.x));}camera.orthographicSize=Mathf.Max(h,w/camera.aspect)*1.2f;var previous=RenderTexture.active;try{camera.Render();RenderTexture.active=texture;var image=new Texture2D(texture.width,texture.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,texture.width,texture.height),0,0);image.Apply();File.WriteAllBytes(Path.Combine(output,Ids[index]+".png"),image.EncodeToPNG());Object.Destroy(image);}finally{RenderTexture.active=previous;}index++;if(index<Ids.Length)Pose();else done();}
}
